#!/usr/bin/env bash
# dbchar_g7b_stage1_extended_report - reruns the gate END TO END FROM THIS ASSEMBLED BUNDLE (BS-3).
#
# This gate is a REPORTING LAYER over the landed Stage-1 bundles and the registered derived
# datasets. It measures nothing new: c01 compares every quantity it re-derives against the value
# the landed gate published and STOPS on any disagreement, and the assembler resolves every number
# in the report from a table landed here.
#
# Measured on borg: ~4 min wall, peak RSS ~12 GB, single process. Needs data/derived/ (gitignored;
# regenerated by the g2/g2b/g3/g4/g6 bundles' own run.sh in ~20 min).
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
S="$HERE/scripts"
ROOT="$(cd "$HERE/../.." && pwd)"
WORK="$ROOT/ARIS_OUTPUT/rerun-dbchar_g7b_stage1_extended_report"

export PATH=/home/borg/miniconda3/envs/retron_tradicional/bin:$PATH
# matplotlib's compiled extensions need this env's libstdc++ ahead of the system one; without it
# `import matplotlib` fails with CXXABI_1.3.15 not found once pandas has loaded the system lib.
export LD_LIBRARY_PATH=/home/borg/miniconda3/envs/retron_tradicional/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}
export MPLCONFIGDIR="${MPLCONFIGDIR:-$WORK/.mpl}"
export G7B_ROOT="$ROOT"
export G7B_DERIVED="$ROOT/data/derived"
export G7B_RESULTS="$ROOT/results"
export G7B_WORK="$WORK"
PY=/home/borg/miniconda3/envs/retron_tradicional/bin/python
mkdir -p "$WORK/tables" "$WORK/figures" "$WORK/meta" "$WORK/cache" "$MPLCONFIGDIR"

if [ ! -d "$G7B_DERIVED" ]; then
  echo "FATAL: $G7B_DERIVED is absent. It is gitignored; regenerate it with the run.sh of" >&2
  echo "       dbchar_g2_canonical_units, _g2b_, _g3_, _g4_ and _g6_ first." >&2
  exit 2
fi

echo "== guard: the assembler must REFUSE a number it cannot resolve from a landed table"
if "$PY" - "$S" "$WORK" <<'GUARD' >/dev/null 2>&1
import pathlib, runpy, sys
sys.path.insert(0, sys.argv[1])
import findings as F
F.SECTIONS = [dict(F.SECTIONS[0])]
F.SECTIONS[0]["prose"] = [("Seeded", "an undeclared {placeholder_that_has_no_lookup} must fail")]
sys.argv = ["assemble_report.py", "--work", sys.argv[2], "--out", sys.argv[2] + "/guard"]
runpy.run_path(pathlib.Path(sys.argv[0]).parent / "assemble_report.py", run_name="__main__")
GUARD
then echo "FATAL: the assembler ACCEPTED an unresolvable placeholder - it is untested." >&2; exit 1; fi
echo "   refused the unresolvable placeholder, as required"

echo "== a01 sections 1-3: units, redundancy, family composition, RT length"
"$PY" "$S/a01_units_families.py"
echo "== a02 sections 4-5: ncRNA models and RT<->ncRNA geometry"
"$PY" "$S/a02_geometry.py"
echo "== a03 sections 6-7: tool combinations, carriage, the zero-call class"
"$PY" "$S/a03_tools_zero_call.py"
echo "== a04 sections 8-10: pair topology, candidates, MULTI"
"$PY" "$S/a04_pairs_candidates_multi.py"
echo "== a05 sections 11-13: taxonomy with denominators, data quality, recurrence breadth"
"$PY" "$S/a05_taxonomy_quality.py"

echo "== c01 reconcile every re-derived value against the landed g1-g6 value (STOPS on mismatch)"
"$PY" "$S/c01_reconcile.py"
echo "== c02 independent intervening-CDS recount from rt_window_cds_v1"
"$PY" "$S/c02_independent_cds_between.py"
echo "== c03 self-validation: the controls must reject a seeded-bad expectation"
if "$PY" "$S/c03_controls.py" --seed-bad >/dev/null 2>&1; then
  echo "FATAL: the controls ACCEPTED a seeded-bad expectation - they are untested." >&2; exit 1; fi
echo "   rejected the seeded-bad case, as required"
"$PY" "$S/c03_controls.py"

echo "== figures (each reads tables/ and nothing else)"
"$PY" "$S/f01_corpus.py"
"$PY" "$S/f02_geometry.py"
"$PY" "$S/f03_tools_taxonomy.py"

echo "== guard: no figure script may open anything outside tables/"
if grep -nE "derived\(|read_parquet|landed\(" "$S"/f0*.py; then
  echo "FATAL: a figure script reads outside tables/ - it could disagree with the table beside it." >&2
  exit 1
fi
echo "   figure scripts read only tables/"

echo "== assemble the report (computes nothing)"
"$PY" "$S/assemble_report.py" --work "$WORK" --out "$WORK"

echo "== BS-3 / WA-B.2: does this reproduce the landed artifacts byte for byte?"
rc=0
cmp_one() {
  if [ ! -f "$WORK/$1" ]; then echo "  MISSING on rerun: $1"; rc=1; return; fi
  if cmp -s "$HERE/$1" "$WORK/$1"; then :; else echo "  DIFF $1"; rc=1; fi
}
n=0
for f in "$HERE"/tables/*.tsv;  do cmp_one "tables/$(basename "$f")"; n=$((n+1)); done
echo "  compared $n tables"
n=0
for f in "$HERE"/figures/*;     do cmp_one "figures/$(basename "$f")"; n=$((n+1)); done
echo "  compared $n figure files"
cmp_one REPORT.html
cmp_one REPORT.md
for f in "$WORK"/tables/*.tsv; do b="$(basename "$f")"; [ -f "$HERE/tables/$b" ] || { echo "  NEW on rerun: tables/$b"; rc=1; }; done
for f in "$WORK"/figures/*;    do b="$(basename "$f")"; [ -f "$HERE/figures/$b" ] || { echo "  NEW on rerun: figures/$b"; rc=1; }; done
if [ "$rc" -eq 0 ]; then echo "REPRODUCED: every landed table, figure and document is byte-identical on rerun."
else echo "NOT REPRODUCED - see the DIFF/MISSING/NEW lines above." >&2; fi
exit "$rc"
